'use strict';importScripts('vendor/sql-wasm.js');let db;
self.onmessage=async e=>{try{if(e.data.type==='init'){const SQL=await initSqlJs({locateFile:()=>new URL('vendor/sql-wasm.wasm',self.location.href).href});db=new SQL.Database();db.run('CREATE TABLE incidents(year INTEGER, month INTEGER, primary_type TEXT, community_area INTEGER, arrest INTEGER, domestic INTEGER, n INTEGER); BEGIN TRANSACTION;');const insert=db.prepare('INSERT INTO incidents VALUES(?,?,?,?,?,?,?)');for(const r of e.data.rows)insert.run(r);insert.free();db.run('COMMIT; CREATE INDEX idx_year_type ON incidents(year,primary_type); PRAGMA query_only=ON;');self.postMessage({type:'ready'});}else{let sql=e.data.sql.trim();if(!/^(select|with)\b/i.test(sql)||sql.includes(';'))throw Error('Only one SELECT or WITH query is permitted.');let result=db.exec('SELECT * FROM ('+sql+') LIMIT 1000');self.postMessage({type:'result',result:result[0]||{columns:[],values:[]}})}}catch(e){self.postMessage({type:'result',error:e.message})}};
